'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Stat, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './stat.css'

/**
 * Stat: every number a player reads.
 *
 * Score, timer, lives, streak, rank, multiplier, level and XP are one component
 * with a different `kind`, not eight components. They differ in the word beside
 * the number and in which token sizes them; they do not differ in how a number
 * is rendered, counted up, or announced. Eight implementations of that would be
 * eight sets of the same bug, and the first theme to land would show it.
 *
 * It performs nothing. It does not count down, fetch, or decide when a value is
 * critical. The host owns the number and says what it means; this renders it and
 * reports nothing back.
 *
 * ## Presentation (GSUI-100)
 *
 * The design draws six game-state objects as six shapes: score as a ringed chip,
 * the timer as a filled pill that changes at two thresholds, lives as a pill of
 * dots, the streak as a pill, the round as a row of segment pills. All six were
 * built as a label above a number on the page background, so a player reading a
 * HUD could not tell the timer from the score except by the word above it.
 *
 * `presentation` is the fix, and it is a prop for the same reason `choice` has
 * one: six silhouettes is not six components. The engine — the number, the
 * count, the accessible name, every state and every attribute — is identical in
 * all five, and only the container changes. `dots` and `pips` additionally draw
 * a row of marks, derived from the same `value` and `max` the number already
 * carries, so nothing is a second place the number is written down.
 *
 * `plain` is the default and is what every stat rendered before this existed, so
 * a host that has never heard of the prop sees no change.
 */

export type StatKind =
  | 'score'
  | 'timer'
  | 'lives'
  | 'streak'
  | 'round'
  | 'status'
  | 'rank'
  | 'multiplier'
  | 'level'
  | 'xp'

/**
 * The silhouette, never the meaning.
 *
 * `plain` is a label above a number, on whatever is behind it. `chip` rings it.
 * `pill` fills it. `dots` and `pips` add a row of marks to the pill, one per
 * unit of `max`: `dots` for a resource that is spent and can come back, `pips`
 * for a position in a sequence.
 */
export type StatPresentation = 'plain' | 'chip' | 'pill' | 'dots' | 'pips'

export type StatSettlement = 'optimistic' | 'settled' | 'corrected'

/**
 * What one mark stands for, per presentation.
 *
 * `dots` splits at the value: the first `value` marks are still held and the
 * rest are spent. The spent one is drawn as a dashed outline rather than a
 * different fill, because the design's dashed slot is what says "this can come
 * back" — which is the thing a broken heart said the opposite of.
 *
 * `pips` splits at the value too, but the value is a 1-based position rather
 * than a count, so the mark at `value` is the one the player is on.
 */
function markStates(presentation: StatPresentation, value: number, max: number): string[] {
  const total = Math.max(0, Math.floor(max))
  // Clamped for the drawing only. `data-gs-value` keeps whatever the host said:
  // a host passing 4 of 3 has a bug, and the attribute is where it should show.
  const held = Math.max(0, Math.min(Math.floor(value), total))
  if (presentation === 'dots') {
    return Array.from({ length: total }, (_, i) => (i < held ? 'held' : 'spent'))
  }
  return Array.from({ length: total }, (_, i) =>
    i < held - 1 ? 'done' : i === held - 1 ? 'current' : 'coming',
  )
}

export interface StatProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Which number this is. Picks the word and the token scale, nothing else. */
  kind: StatKind
  /** The settled value. Always the truth, even mid count-up. */
  value: number
  /** The ceiling, for a bounded value: lives out of three, step two of five. */
  max?: number
  /** The floor, when it is not zero. */
  min?: number
  /** How much it just moved, signed. Renders as a change beside the number. */
  delta?: number
  /**
   * Whether the host has confirmed this number. Absent means it was never in
   * doubt. `optimistic` is a local render the host has yet to reconcile, and
   * `corrected` is the host disagreeing with what the player already saw.
   */
  settlement?: StatSettlement
  /** Time or resource nearly gone. The host decides where that line is. */
  critical?: boolean
  /**
   * Time or resource going, but not nearly gone: the step before `critical`.
   * The host decides where that line is too. Setting both is allowed and
   * critical wins the drawing, the way `disabled` wins over `locked`.
   */
  warning?: boolean
  /** The silhouette. Does not change what the number means or how it is announced. */
  presentation?: StatPresentation
  /** Which way it travels on its own. A timer needs it; one sample cannot say. */
  direction?: 'up' | 'down'
  /** Stopped, not finished. */
  paused?: boolean
  /** Reached the end of its range: a quest done, a timer run out. */
  complete?: boolean
  /** The word beside the number. Defaults to the kind. */
  label?: string
  /** Render the value as something other than the bare number, e.g. `1:30`. */
  format?: (value: number) => string
  /**
   * What to show on screen when it differs from what should be announced. A
   * count-up passes the number mid-flight here; `value` stays the settled one,
   * so the accessible name never reads a number the player is not keeping.
   * Without this a wrapper has to build a second root and mirror the name,
   * which is how a second state vocabulary gets born.
   */
  display?: string
  /**
   * The registry item name a wrapper wants on the root. `score`, `timer`,
   * `lives` and `streak` are their own components to a host and to a test, and
   * a HUD carrying three of these needs to tell them apart, so a wrapper says
   * which one it is rather than every one of them reading `stat`.
   */
  component?: string
}

/**
 * The words that go with the states, from the attribute contract. They live
 * here so that score, timer, lives and streak cannot ship four vocabularies for
 * the same three states.
 */
const STATE_WORD = {
  critical: 'running out',
  warning: 'going',
  paused: 'paused',
  corrected: 'updated',
  complete: 'complete',
} as const

export function Stat({
  kind,
  value,
  max,
  min,
  delta,
  settlement,
  critical = false,
  warning = false,
  presentation = 'plain',
  direction,
  paused = false,
  label,
  format,
  display,
  component = 'stat',
  complete = false,
  className,
  ...rest
}: StatProps) {
  // What is announced is always the settled value. What is rendered may be
  // mid-animation. Keeping them separate is the whole reason `display` exists.
  const announced = format ? format(value) : String(value)
  const rendered = display ?? announced

  // The name carries the state, because a screen reader user gets no colour, no
  // glyph and no motion. Order matters: what it is, then the number, then what
  // is true about it.
  const words = [label ?? kind, max === undefined ? announced : `${announced} of ${max}`]
  // Critical is the stronger claim, so a stat that is both says the stronger
  // word once rather than both words in a row.
  if (critical) words.push(STATE_WORD.critical)
  else if (warning) words.push(STATE_WORD.warning)
  if (paused) words.push(STATE_WORD.paused)
  if (complete) words.push(STATE_WORD.complete)
  if (settlement === 'corrected') words.push(STATE_WORD.corrected)

  // Marks are a drawing of `value` against `max`, so there is nothing to draw
  // without a `max`. A marked presentation with no ceiling degrades to the
  // number rather than throwing or rendering an empty row: a host that has not
  // said how many lives there are has a bug in its props, not in its game.
  const marks =
    (presentation === 'dots' || presentation === 'pips') && max !== undefined
      ? markStates(presentation, value, max)
      : []

  return (
    <div
      {...rest}
      className={['gs-stat', className].filter(Boolean).join(' ')}
      data-gs-component={component}
      data-gs-stat={kind}
      data-gs-presentation={presentation}
      data-gs-value={value}
      data-gs-max={max}
      data-gs-min={min}
      data-gs-delta={delta}
      data-gs-settlement={settlement}
      data-gs-critical={critical ? 'true' : undefined}
      data-gs-warning={warning ? 'true' : undefined}
      data-gs-direction={direction}
      data-gs-paused={paused ? 'true' : undefined}
      data-gs-complete={complete ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      <span className="gs-stat__label" data-gs-scope="stat" data-gs-part="label" aria-hidden="true">
        {label ?? kind}
      </span>
      {/* aria-hidden throughout: the group's label above is the accessible name,
          and announcing the pieces again would read the number twice. */}
      <span className="gs-stat__value gs-display-type" data-gs-scope="stat" data-gs-part="value" aria-hidden="true">
        {rendered}
        {/* The marks already draw the ceiling, so "1/3" beside three dots is the
            same fact twice and the design draws neither lives nor rounds that
            way. `data-gs-max` and the accessible name still carry it. */}
        {max !== undefined && marks.length === 0 ? (
          <span className="gs-stat__max">/{max}</span>
        ) : null}
      </span>
      {marks.length ? (
        // One element for the whole row rather than one attribute per mark: the
        // number lives on the root, and a mark carrying its own state would be a
        // second place to read it from. `emphasis`, not `motion`: the marks
        // change shape and never move, which is the whole point of drawing them.
        <span
          className="gs-stat__marks"
          data-gs-scope="stat" data-gs-part="marks"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          {marks.map((state, index) => (
            <span key={index} className={`gs-stat__mark gs-stat__mark--${state}`} />
          ))}
        </span>
      ) : null}
      {delta !== undefined && delta !== 0 ? (
        // The change moves, so it is motion and stops dead under reduced
        // motion. Its colour is carried by the sign in the attribute, which is
        // emphasis and survives, so a player who cannot see it move still sees
        // which way it went.
        <span
          className="gs-stat__delta"
          data-gs-scope="stat" data-gs-part="delta"
          data-gs-animates="motion"
          aria-hidden="true"
        >
          {delta > 0 ? '+' : '−'}
          {Math.abs(delta)}
        </span>
      ) : null}
      {critical ? (
        <span
          className="gs-stat__glyph"
          data-gs-scope="stat" data-gs-part="glyph"
          data-gs-animates="emphasis"
          aria-hidden="true"
        >
          !
        </span>
      ) : null}
    </div>
  )
}

/* Stat. Every value comes from a token; nothing here is a literal colour. */

.gs-stat {
  display: inline-grid;
  grid-template-areas: 'label glyph' 'value delta';
  grid-template-columns: auto auto;
  align-items: baseline;
  gap: 0 var(--gs-space-2);
}

.gs-stat__label {
  grid-area: label;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  letter-spacing: var(--gs-type-label-letter-spacing);
  text-transform: uppercase;
  color: var(--gs-color-ink-secondary);
}

/* Tabular numerals, or the whole row shifts every time a digit changes and the
   number reads as jittering rather than counting. */
.gs-stat__value {
  grid-area: value;
  /* A display number sets its own leading.

     It had none, so it inherited the page's body line-height: a 36px score sat
     in a 57.6px line box, 60% taller than the glyphs, and the container grew to
     fit it. That is what made a score chip 78px tall beside 55px pills in the
     same HUD row, and it is why the shapes read as irregular before anybody
     could say why.

     1 rather than a token: these are tabular numerals with no descenders doing
     the work, and the box's own padding is what gives them room. */
  line-height: 1;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink);
  /* Colour is emphasis: it changes when the value turns critical and must
     survive reduced motion, because it is how a player who cannot see the
     pulse still knows. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

/* Score is the one a player looks at from across a room. */
.gs-stat[data-gs-stat='score'] .gs-stat__value {
  font-family: var(--gs-type-score-font-family);
  font-size: var(--gs-type-score-font-size);
  font-weight: var(--gs-type-score-font-weight);
}

.gs-stat__max {
  font-size: var(--gs-type-label-font-size);
  color: var(--gs-color-ink-secondary);
}

.gs-stat__delta {
  grid-area: delta;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-positive);
  transition: transform var(--gs-motion-float-up) ease-out;
}

/* The sign carries the colour, so it survives reduced motion even though the
   float does not. */
.gs-stat[data-gs-delta^='-'] .gs-stat__delta { color: var(--gs-color-negative); }

.gs-stat__glyph {
  grid-area: glyph;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  color: var(--gs-color-warning);
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* Critical changes the fill, adds a glyph, and changes the accessible name.
   Never colour alone.

   It used to bump the weight to 900 as a third signal. That is a signal only in
   a theme whose display face has more than one weight: arcade's is Bungee,
   which ships one, so the browser faux-bolded it and the numerals smeared into
   each other. A signal that destroys legibility in the state where reading the
   number matters most is not a signal. The fill, the glyph and the name carry
   it, and all three work in every theme. */
.gs-stat[data-gs-critical='true'] .gs-stat__value {
  color: var(--gs-color-warning);
}

/* A paused clock is not a stopped one. It dims and keeps its place. */
.gs-stat[data-gs-paused='true'] .gs-stat__value { color: var(--gs-color-ink-secondary); }

/* An optimistic number is the player's, not yet the host's. It reads as real,
   because it is what the player will keep in almost every case; the only
   difference is that it has not settled. */
.gs-stat[data-gs-settlement='optimistic'] .gs-stat__value { opacity: 0.85; }

/* A correction is worth noticing, so it is emphasis rather than a silent swap. */
.gs-stat[data-gs-settlement='corrected'] .gs-stat__value {
  color: var(--gs-color-warning);
}

/* -- the silhouettes (GSUI-100) ------------------------------------------- */
/* Container and marks, and nothing else. Not one rule below changes the number,
   its name or any state: those are identical in all five presentations, which is
   why this is a prop rather than five components. stat.tsx has the reasoning. */

/* Everything but `plain` is a container, so they share the box. */
.gs-stat[data-gs-presentation='chip'],
.gs-stat[data-gs-presentation='pill'],
.gs-stat[data-gs-presentation='dots'],
.gs-stat[data-gs-presentation='pips'] {
  /* One height for every container, so a row of them is a row.

     They used to size to their contents with identical padding, and a score's
     number is 36px against everything else's 22px, so the score chip stood 78px
     against the pills' 55px. Twenty-three pixels of difference in a single HUD
     row, which reads as irregular before a reader can say why.

     `size.actionLarge` rather than a new token: it is the tallest thing the
     library already stands in a row, and a score at 36px needs 59px of it. The
     number keeps its size; the box stops taking its size from the number. */
  min-height: var(--gs-size-action-large);
  box-sizing: border-box;
  padding: var(--gs-space-2) var(--gs-space-3);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid transparent;
  /* Emphasis: fill and stroke are the timer's thresholds, and a threshold a
     player only sees if they can see animation is not a threshold. */
  transition:
    background-color var(--gs-motion-emphasis) ease-out,
    border-color var(--gs-motion-emphasis) ease-out;
}

/* Ringed, not filled: a score is read across a room, and a fill behind
   display-sized numerals costs more contrast than it buys. */
.gs-stat[data-gs-presentation='chip'] {
  border-color: var(--gs-color-edge-high);
  border-radius: var(--gs-radius-md);
  background: var(--gs-color-surface-raised);
}

/* `dots` and `pips` are pills that also carry a row of marks. */
.gs-stat[data-gs-presentation='pill'],
.gs-stat[data-gs-presentation='dots'],
.gs-stat[data-gs-presentation='pips'] {
  position: relative;
  border-radius: var(--gs-radius-full);
  background: var(--gs-color-surface-raised);
}

/* One row, not three.

   The marks used to sit under the number with the label above it, which is
   three stacked rows and forces the pill into a circle: lives and round both
   came out as discs with the content crammed into a corner and two thirds of
   the shape empty. The design draws a wide pill holding the marks, with the
   count beside them.

   The label is hidden from the eye and kept in the accessible name, the same
   way the timer's is, so a screen reader still hears "Lives, 2 of 3". */
.gs-stat[data-gs-presentation='dots'],
.gs-stat[data-gs-presentation='pips'] {
  grid-template-areas: 'value marks delta glyph';
  grid-template-columns: auto auto auto auto;
  align-items: center;
  justify-items: start;
  gap: var(--gs-space-2);
  padding: var(--gs-space-2) var(--gs-space-4);
}


/* -- the timer's three thresholds ----------------------------------------- */
/* Running, going, running out: a solid fill, then an outline, then a solid fill
   in another hue with the `!` beside it. Three shapes before three colours, so a
   player who cannot tell the hues apart still gets three answers. */
/* A running timer is the resting state, so it takes the raised surface, not the
   accent. It used to take `interactive`, which arcade defines as the orange
   gradient, so a timer with three minutes left looked exactly like the design's
   warning state. The drawing is explicit: blue while it is running, gold only at
   the warning threshold, red only at critical. Painting the calm state in the
   alarm colour teaches a player the wrong thing, which is worse than looking
   different from the drawing. */
.gs-stat[data-gs-presentation='pill'][data-gs-stat='timer'] {
  background: var(--gs-color-surface-raised);
}

/* The time stands alone. The design draws no label inside the pill, and
   stacking one above the number turned a wide pill into a circle with the
   numerals squashed into the bottom half. The label stays in the accessible
   name, so a screen reader still hears "Time left, 3 minutes 42": it is hidden
   from the eye, not removed. */
/* A pill is one row, and its label is heard rather than seen.

   The design draws a pill holding the thing itself: the time, the streak, the
   row of life marks. It never puts the word "TIMER" or "STREAK" inside. Ours
   stacked the label above the value, which is two rows, which forces the pill
   into a circle: timer, streak, lives and round all came out as discs with the
   content crammed into one corner.

   The label stays in the accessible name, so a screen reader still hears
   "Streak, 4". Hidden from the eye, not removed. */
.gs-stat[data-gs-presentation='pill'] {
  grid-template-areas: 'value marks delta glyph';
  grid-template-columns: auto auto auto auto;
  align-items: center;
  justify-items: start;
  gap: var(--gs-space-2);
  padding: var(--gs-space-2) var(--gs-space-4);
}

/* A chip keeps its label, beside the number rather than above it: the design
   draws "SCORE 12,450" on one line inside an outlined chip. */
.gs-stat[data-gs-presentation='chip'] {
  grid-template-areas: 'label value delta glyph';
  grid-template-columns: auto auto auto auto;
  align-items: baseline;
  gap: var(--gs-space-2);
}

.gs-stat[data-gs-presentation='pill'] .gs-stat__label,
.gs-stat[data-gs-presentation='dots'] .gs-stat__label,
.gs-stat[data-gs-presentation='pips'] .gs-stat__label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}


.gs-stat[data-gs-presentation='pill'][data-gs-warning='true'] {
  background: var(--gs-color-surface);
  border-color: var(--gs-color-warning);
}

/* After warning in the file, so the stronger claim wins when a host sets both. */
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] {
  background: var(--gs-color-negative);
  border-color: var(--gs-color-negative);
  color: var(--gs-color-on-bright);
}

/* On a filled pill the ink comes from the fill, not the page, or a light-on-dark
   theme draws a dark number on a dark fill. */
.gs-stat[data-gs-presentation='pill'][data-gs-stat='timer'] .gs-stat__value,
.gs-stat[data-gs-presentation='pill'][data-gs-stat='timer'] .gs-stat__label,
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__value,
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__label {
  color: inherit;
}

/* And no display shadow on a pill whose ink is dark. arcade's display shadow is
   a hard offset in `color.edge`, which is near-black: behind white numerals it
   reads as depth, behind the dark ink of a filled critical pill it is the same
   colour as the glyph and smears it. Measured: text oklch(0.22 0.09 272) with a
   shadow of oklch(0.2 0.09 272). */
.gs-stat[data-gs-presentation='pill'][data-gs-critical='true'] .gs-stat__value {
  text-shadow: none;
}

/* -- the marks ------------------------------------------------------------ */
.gs-stat__marks {
  grid-area: marks;
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-1);
  /* Emphasis: the marks change shape and never move, so they survive reduced
     motion, which is the whole point of drawing them. */
  transition: color var(--gs-motion-emphasis) ease-out;
}

.gs-stat__mark {
  display: block;
  box-sizing: border-box;
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid currentColor;
}

/* Dots: a resource that is spent and can come back. Held is solid; spent is the
   same circle left empty and dashed, which is what says it can come back — a
   broken heart said the opposite, which is why the drawing changed. Fill and
   stroke style both differ, so nothing here depends on the colour. */
.gs-stat[data-gs-presentation='dots'] .gs-stat__mark {
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
}

/* The player's own resource, so the player colour: a life left is not a bad thing. */
.gs-stat[data-gs-presentation='dots'] .gs-stat__marks { color: var(--gs-color-player); }

.gs-stat__mark--held  { background: currentColor; }
.gs-stat__mark--spent {
  background: none;
  border-style: dashed;
  color: var(--gs-color-muted);
}

/* Pips: a position in a sequence. Done is solid, current is solid and wider with
   the reward glow, coming is an empty outline. Two widths and two fills, before
   any colour. */
.gs-stat[data-gs-presentation='pips'] .gs-stat__mark {
  width: var(--gs-space-4);
  height: var(--gs-space-2);
  border-radius: var(--gs-radius-full);
}

.gs-stat__mark--done    { background: currentColor; color: var(--gs-color-positive); }
.gs-stat__mark--current {
  width: var(--gs-space-6);
  background: currentColor;
  color: var(--gs-color-reward);
  box-shadow: var(--gs-depth-reward);
}
.gs-stat__mark--coming  { background: none; color: var(--gs-color-muted); }

/* Down to the last of them. The marks follow the number's own critical state, so
   nothing needs a second attribute. Last, so it wins over the dots' own colour. */
.gs-stat[data-gs-critical='true'] .gs-stat__marks { color: var(--gs-color-warning); }
